,p_static_id=>'lov-applications'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- release 73: the registered applications a row of this page''s setup type may belong to (XXFND_SETUP_TYPES;',
'-- COMMON is the instance: the empty value "All applications (instance)"); delegated: its own application only',
'select a.application_name || '' ('' || a.application_code || '')'' as display_value,',
'       a.application_code as return_value',
'  from xxfnd_applications a',
' where a.enabled_flag = ''Y''',
'   and a.application_code <> ''COMMON''',
'   and xxfnd_setup_type_pkg.app_allowed(xxfnd_setup_type_pkg.page_type(:APP_PAGE_ID), a.application_code) = ''Y''',
'   and (nvl(:G_ADMIN_APP, ''ALL'') = ''ALL'' or a.application_code = :G_ADMIN_APP)',
' order by a.application_name'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'RETURN_VALUE'
,p_display_column_name=>'DISPLAY_VALUE'
);
end;
