,p_plug_name=>'Delegated Mode'
,p_static_id=>'delegated-mode'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>1
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<style>',
'/* release 73: a COMMON screen shown inside another application (its Setup dialog): no COMMON header or menu */',
'.t-Header, .t-Body-nav, .t-Footer, #t_Body_nav { display: none !important; }',
'.t-Body, .t-Body-main, .t-Body-content { margin-left: 0 !important; padding-top: 0 !important; }',
'.t-Body-contentInner { padding-top: 0 !important; }',
'</style>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>':G_ADMIN_LOCK = ''Y'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(40390410320163199)
,p_plug_name=>'Feature Tabs'
,p_static_id=>'feature-tabs'
,p_region_name=>'feature-tabs'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>15
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_list_id=>wwv_flow_imp.id(40379943343162807)
,p_plug_source_type=>'NATIVE_LIST'
,p_list_template_id=>3291129826436920383
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Only on a tab page of a feature that has more than one tab.',
'select 1',
'  from xxfnd_feature_pages c',
' where c.app_alias = :APP_ALIAS',
'   and c.page_id   = :APP_PAGE_ID',
'   and c.tab_label is not null',
'   and (select count(*) from xxfnd_feature_pages t',
'         where t.app_alias = c.app_alias and t.feature_code = c.feature_code',
'           and t.tab_label is not null) > 1'))
);
end;
