prompt --application/deployment/install/install_01_common_tables_xxfnd_part_1_of_3
begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '--------------------------------------------------------------------------------'||wwv_flow.LF||
'-- 01_xxfnd_tables.';
wwv_flow_imp.g_varchar2_table(2) := 'sql'||wwv_flow.LF||
'-- Common, reusable components (XXFND_). Any application in workspace XXCUS'||wwv_flow.LF||
'-- may use these obj';
wwv_flow_imp.g_varchar2_table(3) := 'ects. KYC-specific objects live in 02_xxcmp_tables.sql.'||wwv_flow.LF||
'--'||wwv_flow.LF||
'--   0.0  Lookups, identity and access, n';
wwv_flow_imp.g_varchar2_table(4) := 'otification templates, audit, retention'||wwv_flow.LF||
'--   0.1  Attachments (EBS FND attachments model; UCM or Sha';
wwv_flow_imp.g_varchar2_table(5) := 'rePoint storage)'||wwv_flow.LF||
'--   0.2  Workflow engine'||wwv_flow.LF||
'--   0.4  Integration hub'||wwv_flow.LF||
'--   0.5  Descriptive flexfield';
wwv_flow_imp.g_varchar2_table(6) := 's (EBS structure, Fusion typed segments)'||wwv_flow.LF||
'--'||wwv_flow.LF||
'-- Conventions'||wwv_flow.LF||
'--   * Surrogate keys are identity column';
wwv_flow_imp.g_varchar2_table(7) := 's; stable setup data uses natural keys.'||wwv_flow.LF||
'--   * Every table carries the standard WHO columns; XXFND_U';
wwv_flow_imp.g_varchar2_table(8) := 'TIL_PKG creates the'||wwv_flow.LF||
'--     trigger that fills them and increments OBJECT_VERSION_NUMBER.'||wwv_flow.LF||
'--   * ENAB';
wwv_flow_imp.g_varchar2_table(9) := 'LED_FLAG plus START/END_DATE_ACTIVE where effective dating applies.'||wwv_flow.LF||
'--   * Single-column lookup code';
wwv_flow_imp.g_varchar2_table(10) := 's are validated by LOVs and packages, not by a'||wwv_flow.LF||
'--     foreign key, because XXFND_LOOKUP_VALUES has a';
wwv_flow_imp.g_varchar2_table(11) := ' two-column key (the same'||wwv_flow.LF||
'--     approach as FND_LOOKUP_VALUES).'||wwv_flow.LF||
'--   * _TL tables hold translated t';
wwv_flow_imp.g_varchar2_table(12) := 'ext; LANGUAGE_CODE uses APEX language codes'||wwv_flow.LF||
'--     (''en'', ''ar''). A missing translation falls back to';
wwv_flow_imp.g_varchar2_table(13) := ' the base row.'||wwv_flow.LF||
'--------------------------------------------------------------------------------'||wwv_flow.LF||
''||wwv_flow.LF||
'--=';
wwv_flow_imp.g_varchar2_table(14) := '============================================================================='||wwv_flow.LF||
'-- 0.0  LOOKUPS'||wwv_flow.LF||
'--====';
wwv_flow_imp.g_varchar2_table(15) := '=========================================================================='||wwv_flow.LF||
'begin'||wwv_flow.LF||
'    if xxfnd_ddl_pk';
wwv_flow_imp.g_varchar2_table(16) := 'g.create_table(''XXFND_LOOKUP_TYPES'', q''~create table xxfnd_lookup_types ('||wwv_flow.LF||
'    lookup_type           ';
wwv_flow_imp.g_varchar2_table(17) := ' varchar2(30)   not null,'||wwv_flow.LF||
'    meaning                varchar2(200)  not null,'||wwv_flow.LF||
'    description       ';
wwv_flow_imp.g_varchar2_table(18) := '     varchar2(500),'||wwv_flow.LF||
'    application_code       varchar2(30),'||wwv_flow.LF||
'    customization_level    varchar2(1) ';
wwv_flow_imp.g_varchar2_table(19) := '   default ''U'' not null,'||wwv_flow.LF||
