prompt --application/deployment/install/upgrade_04b_applications_and_users
begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '--------------------------------------------------------------------------------'||wwv_flow.LF||
'-- 04b Applications';
wwv_flow_imp.g_varchar2_table(2) := ' and users - shared access module (release 46)'||wwv_flow.LF||
'--   XXFND_APPLICATIONS: every APEX application that ';
wwv_flow_imp.g_varchar2_table(3) := 'uses the shared access module. APPLICATION_ID is an internal'||wwv_flow.LF||
'--     key (sequence), never changed, u';
wwv_flow_imp.g_varchar2_table(4) := 'sed by the foreign keys (roles, features). APPLICATION_CODE and the APEX alias'||wwv_flow.LF||
'--     are the same i';
wwv_flow_imp.g_varchar2_table(5) := 'n every environment; APEX_APPLICATION_ID is the APEX ID in this environment (DEV / TEST / PROD'||wwv_flow.LF||
'--   ';
wwv_flow_imp.g_varchar2_table(6) := '  may differ) and is kept up to date at sign-in (release 47).'||wwv_flow.LF||
'--   XXFND_USERS: the users of all app';
wwv_flow_imp.g_varchar2_table(7) := 'lications. A user linked to an employee (USER_TYPE SSO) signs in with the'||wwv_flow.LF||
'--     identity domain onl';
wwv_flow_imp.g_varchar2_table(8) := 'y; a LOCAL user (no employee) has an Oracle APEX account (APEX keeps the password),'||wwv_flow.LF||
'--     created f';
wwv_flow_imp.g_varchar2_table(9) := 'rom the access console (XXFND_USER_PKG).'||wwv_flow.LF||
'--   XXFND_USER_ROLES.USER_ID: grants belong to the user (E';
wwv_flow_imp.g_varchar2_table(10) := 'MPLOYEE_ID kept for the grants made before release 46;'||wwv_flow.LF||
'--     trigger XXFND_USER_ROLES_USER fills US';
wwv_flow_imp.g_varchar2_table(11) := 'ER_ID from it).'||wwv_flow.LF||
'-- Idempotent: safe on install and on every upgrade.'||wwv_flow.LF||
'-------------------------------';
wwv_flow_imp.g_varchar2_table(12) := '-------------------------------------------------'||wwv_flow.LF||
'create sequence if not exists xxfnd_applications_s';
wwv_flow_imp.g_varchar2_table(13) := ' start with 1000 nocache;'||wwv_flow.LF||
''||wwv_flow.LF||
